function i(r){const t=Number(r)||0;return new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",minimumFractionDigits:0,maximumFractionDigits:0}).format(t)}function n(r){return r?new Intl.DateTimeFormat("id-ID",{year:"numeric",month:"short",day:"2-digit",hour:"2-digit",minute:"2-digit"}).format(new Date(r)):"—"}function a(r){if(!r)return"—";const t=(Date.now()-new Date(r).getTime())/1e3;return t<60?"baru saja":t<3600?`${Math.floor(t/60)} menit lalu`:t<86400?`${Math.floor(t/3600)} jam lalu`:`${Math.floor(t/86400)} hari lalu`}export{n as a,i as f,a as t};
